```python
BATCH_CONFIG = {
    "environment_config": {
        "execution_config": {
            "subnetwork_uri": "<your-subnet>",
            "network_tags": ["dev", "user0124"], # This is where you can place your tags, I used these dummy values to test
        }
    },
    "spark_batch": {
        "jar_file_uris": ["file:///usr/lib/spark/examples/jars/spark-examples.jar"],
        "main_class": "org.apache.spark.examples.SparkPi",
    },
